const input = ($json && typeof $json.body === 'object' && $json.body !== null) ? $json.body : ($json ?? {});
const clean = (value, max = 500) => String(value ?? '').trim().slice(0, max);
const name = clean(input.name, 120);
const email = clean(input.email, 160).toLowerCase();
const category = clean(input.category, 80) || 'Soporte técnico';
const description = clean(input.description, 500);
const allowedPriorities = ['Urgente', 'Alta', 'Media', 'Baja'];
const priority = allowedPriorities.includes(clean(input.priority, 20)) ? clean(input.priority, 20) : 'Media';
const missing = [];
if (!name) missing.push('name');
if (!email) missing.push('email');
if (!description) missing.push('description');
const validEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const validLength = description.length <= 500;
const valid = missing.length === 0 && validEmail && validLength;
const receivedAt = new Date().toISOString();
const startedAtMs = Date.now();
return [{ json: { name, email, category, priority, description, valid, missing, validEmail, validLength, receivedAt, startedAtMs, workflowVersion: '2.0.0', source: 'flowdesk-web' } }];

const routing = {
  Urgente: { route: 'Atención inmediata', queue: 'priority-critical', slaMinutes: 30 },
  Alta: { route: 'Cola prioritaria', queue: 'priority-high', slaMinutes: 120 },
  Media: { route: 'Cola general', queue: 'standard', slaMinutes: 480 },
  Baja: { route: 'Cola general', queue: 'standard', slaMinutes: 1440 },
};
const selected = routing[$json.priority] || routing.Media;
const requestId = `FD-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`;
const processedAt = new Date().toISOString();
const processingMs = Math.max(0, Date.now() - Number($json.startedAtMs || Date.now()));
return [{ json: {
  status: 'success',
  message: 'Solicitud procesada correctamente',
  requestId,
  priority: $json.priority,
  category: $json.category,
  route: selected.route,
  queue: selected.queue,
  slaMinutes: selected.slaMinutes,
  processedAt,
  receivedAt: $json.receivedAt,
  processingMs,
  source: 'n8n',
  workflowVersion: $json.workflowVersion
} }];

const issues = [];
if (Array.isArray($json.missing) && $json.missing.length) issues.push(`Campos obligatorios ausentes: ${$json.missing.join(', ')}`);
if (!$json.validEmail) issues.push('El correo electrónico no tiene un formato válido');
if (!$json.validLength) issues.push('La descripción supera el máximo de 500 caracteres');
return [{ json: {
  status: 'error',
  message: 'La solicitud contiene datos inválidos',
  errors: issues,
  missing: $json.missing || [],
  validEmail: Boolean($json.validEmail),
  requestId: null,
  processedAt: new Date().toISOString(),
  receivedAt: $json.receivedAt,
  source: 'n8n',
  workflowVersion: $json.workflowVersion
} }];
